const resume = $json.body.resume_text;
const location = $json.body.location;

if (!resume || !location) {
  throw new Error('resume_text and location are required in request body');
}

return [{ json: { resume_text: resume, location: location } }];

const resumeText = $json.resume_text;
const location = $json.location;

const prompt = `You are a professional career analyst. Analyze this resume and return ONLY raw JSON, no markdown, no explanation:

{"experience_level": "fresher", "primary_roles": ["ML Engineer"], "skills": ["Python"], "search_keywords": "machine learning engineer"}

Resume:
${resumeText}`;

try {
  const res = await fetch('http://127.0.0.1:11434/api/generate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'llama3.1:8b', prompt, stream: false })
  });
  const data = await res.json();
  const raw = data.response.replace(/```json/gi,'').replace(/```/g,'').trim();
  const match = raw.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('No JSON in AI response');
  const parsed = JSON.parse(match[0]);
  return [{ json: { ...parsed, location, resume_text: resumeText } }];
} catch(e) {
  return [{ json: {
    experience_level: 'fresher',
    primary_roles: ['Machine Learning Engineer'],
    skills: ['Python', 'TensorFlow'],
    search_keywords: 'machine learning engineer',
    location, resume_text: resumeText, ai_error: e.message
  }}];
}

