let parsed = JSON.parse(clean);

return [{ json: { ...parsed, location: $node["Extract Resume + Location"].json.location } }];

const role = $json.primary_roles[0] || 'Software Engineer';
const location = $json.location;

const query = encodeURIComponent(`${role} ${location}`);
const apiUrl = `https://remotive.com/api/remote-jobs?search=${query}`;

const response = await fetch(apiUrl);
const data = await response.json();

const jobs = (data.jobs || []).slice(0, 15).map(job => ({
  job_title: job.title,
  company_name: job.company_name,
  job_link: job.url,
  location: job.candidate_required_location
}));

return jobs.map(job => ({ json: job }));
